begin;

create table if not exists public.esencialescol_catalog (
  id integer generated by default as identity primary key,
  slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  title text not null,
  category text not null check (category in ('audio', 'tecnologia-personal', 'carga-y-conectividad', 'gaming', 'gadgets-y-accesorios')),
  description text not null default '',
  note text not null default '',
  price integer check (price > 0),
  suggested_price integer check (suggested_price > 0),
  price_tiers jsonb not null default '[]' check (jsonb_typeof(price_tiers) = 'array'),
  featured boolean not null default false,
  published boolean not null default true
);

alter table public.esencialescol_catalog enable row level security;
revoke all on public.esencialescol_catalog from anon, authenticated;
grant select on public.esencialescol_catalog to anon, authenticated;
do $policy$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'public' and tablename = 'esencialescol_catalog' and policyname = 'Read published products'
  ) then
    create policy "Read published products" on public.esencialescol_catalog
      for select to anon, authenticated using (published);
  end if;
end
$policy$;

